import{_ as t,a as i,b as r}from"./chunks/ai-create-03.Cig2rYP0.js";import{_ as e,o,c as n,a3 as l}from"./chunks/framework.D1iekJsc.js";const _=JSON.parse('{"title":"AIで作成","description":"MiniTavern は設定済みモデルに説明と任意の参考画像を渡し、キャラクターカードを生成します。確認して保持したあと作成します。","frontmatter":{"title":"AIで作成","description":"MiniTavern は設定済みモデルに説明と任意の参考画像を渡し、キャラクターカードを生成します。確認して保持したあと作成します。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"AIで作成 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern は設定済みモデルに説明と任意の参考画像を渡し、キャラクターカードを生成します。確認して保持したあと作成します。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/manual/ai-create"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/manual/ai-create"}]]},"headers":[],"relativePath":"ja/manual/ai-create.md","filePath":"ja/manual/ai-create.md","lastUpdated":1791861929000}'),s={name:"ja/manual/ai-create.md"};function c(g,a,p,d,h,u){return o(),n("div",null,[...a[0]||(a[0]=[l('<h1 id="aiで作成" tabindex="-1">AIで作成 <a class="header-anchor" href="#aiで作成" aria-label="Permalink to &quot;AIで作成&quot;">​</a></h1><p>経路：下部 <strong>キャラカード</strong> → <strong>作成 / 取り込み</strong> → <strong>AIで作成</strong>。</p><p>先に <a href="./model-link">モデル接続</a> を用意し、接続テストを成功させてください。使えるモデルがないときは生成できず、設定へ案内されます。</p><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+t+'" alt="AIで作成の入口"><figcaption>1 · 作成 / 取り込み → AIで作成</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="説明と参考画像"><figcaption>2 · モデルを選び、説明を書く</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="確認してキャラクターを作成"><figcaption>3 · 確認してから作成</figcaption></figure></div><h2 id="生成" tabindex="-1">生成 <a class="header-anchor" href="#生成" aria-label="Permalink to &quot;生成&quot;">​</a></h2><ol><li><strong>生成モデル</strong>：設定済みのモデル接続から選びます。既定の接続が最初に選ばれ、別の接続にも切り替えられます。</li><li><strong>説明</strong>（必須）：欲しいキャラクターを一段落で書きます。</li><li><strong>参考画像</strong>（任意）：画像をタップすると拡大し、右上の閉じるアイコンで外せます。画像があるときは、選んだモデルが画像に対応している必要があります。未対応ならモデルを変えるか、画像を外します。</li><li><strong>生成</strong> をタップします。ボタンは「生成中」になり、その間はモデル、説明、参考画像を変えられません。</li></ol><p>参考画像はモデルに人設を見せるためのものです。最初の生成が成功すると、その画像が <strong>キャラクター画像</strong> として入ります。モデルが新しい絵を描くわけではありません。参考画像がないときは、確認画面で自分で画像を選ばないと作成できません。</p><p>生成に失敗すると説明が出ます。「詳細を見る」で理由を確認できます。生成をキャンセルしても失敗の説明は出ません。</p><h2 id="確認と保持" tabindex="-1">確認と保持 <a class="header-anchor" href="#確認と保持" aria-label="Permalink to &quot;確認と保持&quot;">​</a></h2><p>生成に成功すると <strong>キャラクターを確認</strong> に進みます。生成画面自体にはカードの内容は出ません。</p><ul><li>名前、説明、タグ、性格、オープニング、ワールドブックなどは直接直せます。</li><li>各 AI 項目と、ワールドブック全体に <strong>保持</strong> があります。オンにすると、次の再生成でその項目は上書きされません。文字を直しても保持は自動ではオンになりません。</li><li><strong>再生成</strong> は先に入力欄を開きます。直したい点を書くか、空のまま元の説明でもう一度生成します。「保持」がオンの項目とワールドブックはそのままです。すべて保持しているときはリクエストを送りません。</li><li>生成中は「再生成」が読み込み表示になり、「キャラクターを作成」はキャンセルになります。</li><li><strong>キャラクターを作成</strong> は読み込みのあと、作成済みの案内が出ます。作成前に画像、名前、説明が必要です。</li><li>アニメや映像作品など既存作品が原型のときは、ワールドブックを含められます。作成するとカード内にその設定が残り、チャットで使えるワールドブックにもコピーされます。使い方は <a href="./lorebook">ワールドブック</a>。</li><li>作成前に確認画面を離れると、今回の下書きは破棄され、生成画面に戻ります。参考画像は生成画面に残ります。</li></ul><h2 id="関連" tabindex="-1">関連 <a class="header-anchor" href="#関連" aria-label="Permalink to &quot;関連&quot;">​</a></h2><ul><li><a href="./chara-card">キャラカード</a>：取り込み、編集、チャット開始</li><li><a href="./model-link">モデル接続</a>：生成に使うモデルを先に設定</li></ul>',14)])])}const A=e(s,[["render",c]]);export{_ as __pageData,A as default};
